-- Import all Kabs Lily Fees and Student Accounts into Supabase
-- Run this in the Supabase SQL Editor

DO $$
DECLARE
  v_tenant_id text := 'kabs-lily-junior-school-and-kindercare-centre';
BEGIN
  -- Delete existing financial records for clean re-import
  DELETE FROM school_income WHERE tenant_id = v_tenant_id;
  DELETE FROM fees WHERE tenant_id = v_tenant_id;

  -- Insert all fee structures & accounts for Kabs Lily into school_income

  RAISE NOTICE 'Imported fee records into Supabase for tenant %', v_tenant_id;
END $$;
